<section class="card" id="housekeeping-form" tabindex="-1">
<?php if($form==='clean'):$sections=$d['cleaning']['sections'];$selected=$c['done'];if(isset($_POST['done'])&&is_array($_POST['done']))$selected=array_filter($_POST['done'],'is_string');?>
<h2>Cleaning · Step <?=$c['step']+1?> Of <?=count($sections)?></h2><p>Checklist <?=access_h($d['cleaning']['revision'])?> · Current attempts retain their captured checklist.</p>
<form method="post" enctype="multipart/form-data" data-cleaning-form data-step="<?=(int)$c['step']?>"><?php h_fields('progress',$extra);?>
<div class="hk-row"><button type="button" class="secondary" data-select-clean="all">Select All</button><button type="button" class="secondary" data-select-clean="none">Clear All</button><span data-count aria-live="polite"></span></div><p>Select All ticks every cleaning item across all steps. It does not record completion.</p>
<?php foreach($sections as $index=>$section):?><fieldset data-clean-step="<?=(int)$index?>" <?=$index!==$c['step']?'hidden':''?>><legend><?=access_h($section['title'])?></legend><?php foreach($section['items'] as $item):?><label class="hk-check"><input type="checkbox" name="done[]" value="<?=access_h($item['id'])?>" <?=in_array($item['id'],$selected,true)?'checked':''?> <?=$index===$c['step']?'required':''?>><span><?=access_h($item['text'])?></span></label><?php endforeach?></fieldset><?php endforeach?>
<p>Follow product labels and contact times. Never mix cleaning chemicals.</p>
<?php if($c['step']===count($sections)-1):h_text('Comment','comment',false,$c['comment']);h_upload();h_check('verified','I completed these cleaning tasks in person and the checklist is accurate.');endif?>
<div class="hk-row"><button type="submit" name="direction" value="<?=$c['step']===count($sections)-1?'complete':'next'?>" <?=$c['step']===count($sections)-1?'data-confirm="Record cleaning complete? The room remains unavailable until inspection."':''?>><?=$c['step']===count($sections)-1?'Record Cleaning Complete':'Next Step'?></button><?php if($c['step']):?><button type="submit" name="direction" value="previous" formnovalidate class="secondary">Previous Step</button><?php endif?><button type="submit" name="direction" value="pause" formnovalidate class="secondary">Save & Return</button></div></form>
<?php elseif($form==='inspect'):?>
<h2>Inspect & Release Room</h2><p>Cleaner <?=access_h($c['root']['actor_name'])?> · Inspector <?=access_h($user['name'])?> · <?=$cleaner?'Owner-Authorized Self-Inspection':'Independent Inspection'?></p>
<form method="post" enctype="multipart/form-data" data-inspection-form><?php h_fields('inspect',$extra);?><div class="hk-row"><button type="button" class="secondary" data-select-inspect="all">Select All</button><button type="button" class="secondary" data-select-inspect="none">Clear All</button></div><p>Select All marks each item Pass. Change any failed item to Needs Attention.</p>
<?php foreach($d['inspection']['sections'] as $section):foreach($section['items'] as $item):?><fieldset><legend><?=access_h($item['text'])?></legend><div class="hk-row"><?php foreach(['pass'=>'Pass','fail'=>'Needs Attention'] as $value=>$label):?><label class="hk-check"><input type="radio" name="result_<?=access_h($item['id'])?>" value="<?=$value?>" <?=h_value('result_'.$item['id'])===$value?'checked':''?> required><span><?=$label?></span></label><?php endforeach?></div></fieldset><?php endforeach;endforeach;h_text('Comment / Rework Note');h_upload();h_check('verified','I inspected this room in person and these findings are accurate.');?>
<div class="hk-row"><button type="submit" name="decision" value="release" data-confirm="Confirm inspection passed and release this unused, unblocked room?">Confirm & Release Room</button><button type="submit" class="secondary" name="decision" value="rework" data-confirm="Return this room for cleaning and retain these findings?">Return For Cleaning</button><?php h_link('Cancel',['id'=>$c['root']['id']]);?></div></form>
<?php else:$action=match($form){'exception'=>'request_exception','decision'=>'decide_exception','followup'=>'followup','restart'=>'restart'};?>
<h2><?=access_h(match($form){'exception'=>$owner?'Owner Self-Inspection Exception':'Request Self-Inspection Exception','decision'=>'Review Self-Inspection Request','followup'=>'Review Completed Self-Inspection',default=>'Restart Abandoned Attempt'})?></h2>
<?php if($form==='decision'):?><p><?=access_h($c['exception']['data']['reason'])?></p>
<?php elseif($form==='followup'):foreach($c['followups'] as $pending):if((int)$pending['id']===$reviewId):?><p><?=access_h($pending['actor_name'].' · '.display_date($pending['created_at']))?> UTC · <?=access_h($pending['data']['decision'])?></p><?php endif;endforeach?>
<?php elseif($form==='restart'):?><p>The original assignment stays in history. A new physical cleaning attempt will record you as its cleaner.</p><?php endif?>
<form method="post" data-confirm="Record this decision? Exception authorization alone never releases a room."><?php h_fields($action,$extra+($form==='followup'?['inspection_id'=>(string)$reviewId]:[]));h_text(match($form){'exception'=>'Why An Independent Inspector Is Unavailable','followup'=>'Follow-Up Review Outcome','restart'=>'Why A Fresh Attempt Is Needed',default=>'Decision Note'},'reason',true);?>
<div class="hk-row"><?php if($form==='decision'):?><button type="submit" name="decision" value="approve">Authorize This Attempt</button><button class="secondary" type="submit" name="decision" value="reject">Decline Exception</button><?php else:?><button type="submit"><?=access_h(match($form){'exception'=>$owner?'Authorize This Self-Inspection Attempt':'Send To Eugene','followup'=>'Record Owner Review',default=>'Start Fresh Cleaning'})?></button><?php endif;h_link('Cancel',['id'=>$c['root']['id']]);?></div></form>
<?php endif?></section>
